  (6, 'I''m working on it', 'Indicating progress is being made.', 'The report isn''t done, but I''m working on it. (Tôi đang làm rồi.)', (select id from public.categories where slug = 'daily-communication')),
  (7, 'Sounds good', 'Indicating agreement or approval.', 'Meet at 5 PM? Sounds good to me. (Nghe được đấy.)', (select id from public.categories where slug = 'daily-communication')),
