  (10, 'I''m down for that', 'Agreeing to join an activity.', 'Want to go to the beach? - I''m down for that! (Tôi duyệt luôn!)', (select id from public.categories where slug = 'daily-communication')),
  (11, 'It is what it is', 'Accepting a difficult situation.', 'We lost the contract. Well, it is what it is. (Đành chấp nhận vậy.)', (select id from public.categories where slug = 'daily-communication')),
