  (30, 'Good for you', 'Expressing approval for good news.', 'I got promoted! - Good for you! (Chúc mừng bạn!)', (select id from public.categories where slug = 'daily-communication')),
  (31, 'I have no clue', 'Having absolutely no idea.', 'How does this work? - I have no clue. (Tôi chịu chết.)', (select id from public.categories where slug = 'daily-communication')),
  (32, 'I can''t believe it', 'Expressing profound shock.', 'We won! I can''t believe it! (Không thể tin được!)', (select id from public.categories where slug = 'daily-communication')),
  (33, 'That''s a shame', 'Expressing mild disappointment.', 'She missed the flight. - That''s a shame. (Thật đáng tiếc.)', (select id from public.categories where slug = 'daily-communication')),
  (34, 'It''s not a big deal', 'Something is minor and not worth worrying about.', 'Don''t worry, it''s not a big deal. (Không có gì to tát đâu.)', (select id from public.categories where slug = 'daily-communication')),
  (35, 'Looking forward to it', 'Excitement for a future event.', 'I can''t wait. I''m looking forward to it. (Tôi rất mong chờ.)', (select id from public.categories where slug = 'daily-communication')),
  (36, 'Worth a shot', 'Worth trying, even if it might fail.', 'It''s risky, but it''s worth a shot. (Đáng để thử.)', (select id from public.categories where slug = 'daily-communication')),
  (37, 'I mean it', 'Being completely serious.', 'You did an amazing job, I mean it. (Tôi nói thật lòng đấy.)', (select id from public.categories where slug = 'daily-communication')),
  (38, 'Better get going', 'Time to leave.', 'It''s late, I''d better get going. (Tôi nên đi thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (39, 'I know, right?', 'Showing strong agreement.', 'The weather is beautiful. - I know, right? (Đúng thế chứ lị?)', (select id from public.categories where slug = 'daily-communication')),
  (40, 'You can say that again', 'Absolute agreement.', 'This is delicious. - You can say that again! (Bạn nói quá chuẩn!)', (select id from public.categories where slug = 'daily-communication')),
  (41, 'I''d rather not', 'Politely declining.', 'Watch a horror movie? - I''d rather not. (Tôi không muốn lắm.)', (select id from public.categories where slug = 'daily-communication')),
  (42, 'I''m telling you', 'Emphasizing the truth.', 'I''m telling you, this is the best deal. (Tôi nói thật cho bạn biết đấy.)', (select id from public.categories where slug = 'daily-communication')),
  (43, 'That''s how it goes', 'Accepting an unchangeable reality.', 'We lost, but that''s how it goes. (Cuộc sống là thế mà.)', (select id from public.categories where slug = 'daily-communication')),
  (44, 'No can do', 'An informal way to say you cannot do something.', 'Lend me $50? - Sorry, no can do. (Không được rồi.)', (select id from public.categories where slug = 'daily-communication')),
  (45, 'Small world', 'Meeting unexpectedly in an unlikely place.', 'Running into you here! It''s a small world. (Thế giới nhỏ bé thật.)', (select id from public.categories where slug = 'daily-communication')),
  (46, 'Didn''t mean to', 'Clarifying an action was an accident.', 'I didn''t mean to break your cup. (Tôi không cố ý.)', (select id from public.categories where slug = 'daily-communication')),
  (47, 'Beside the point', 'Irrelevant to the main issue.', 'We are talking about quality, color is beside the point. (Không liên quan.)', (select id from public.categories where slug = 'daily-communication')),
  (48, 'I''m all ears', 'Ready to listen attentively.', 'Tell me your idea, I''m all ears. (Tôi đang toàn tâm lắng nghe đây.)', (select id from public.categories where slug = 'daily-communication')),
  (49, 'Keep in touch', 'Maintain communication.', 'Good luck, let''s keep in touch! (Giữ liên lạc nhé!)', (select id from public.categories where slug = 'daily-communication')),
