  (53, 'Pitch in', 'To contribute to a group effort.', 'If we all pitch in, it''ll be fast. (Nếu cùng góp sức, sẽ nhanh thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (54, 'Face the music', 'Accept negative consequences.', 'You made a mistake, time to face the music. (Đối mặt hậu quả thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (55, 'Ring a bell', 'Sound familiar.', 'That name rings a bell. (Cái tên đó nghe quen quen.)', (select id from public.categories where slug = 'daily-communication')),
