  (61, 'Under the weather', 'Feeling slightly ill.', 'I''m a bit under the weather today. (Hôm nay tôi hơi không khỏe.)', (select id from public.categories where slug = 'daily-communication')),
  (62, 'Spill the beans', 'Reveal a secret.', 'Come on, spill the beans about the surprise! (Khai bí mật ra đi!)', (select id from public.categories where slug = 'daily-communication')),
  (63, 'Bite the bullet', 'Endure something difficult but necessary.', 'I have to bite the bullet and pay the fine. (Phải cắn răng mà nộp phạt thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (64, 'Call it a night', 'Stop an activity for the rest of the night.', 'We''ve worked enough, let''s call it a night. (Tối nay nghỉ ở đây thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (65, 'Cut corners', 'Do something poorly to save time/money.', 'Don''t cut corners on software security. (Đừng đốt cháy giai đoạn về bảo mật.)', (select id from public.categories where slug = 'daily-communication')),
  (66, 'Get out of hand', 'Lose control of a situation.', 'The argument got out of hand quickly. (Cuộc cãi vã vượt quá tầm kiểm soát.)', (select id from public.categories where slug = 'daily-communication')),
  (67, 'Miss the boat', 'Miss a good opportunity.', 'Buy the stock now or you''ll miss the boat. (Sẽ lỡ cơ hội nếu không mua giờ.)', (select id from public.categories where slug = 'daily-communication')),
  (68, 'Pull someone''s leg', 'To joke or tease someone.', 'Are you serious or just pulling my leg? (Bạn đang đùa tôi à?)', (select id from public.categories where slug = 'daily-communication')),
