  (70, 'Cost an arm and a leg', 'To be very expensive.', 'This designer bag costs an arm and a leg. (Chiếc túi này đắt cắt cổ.)', (select id from public.categories where slug = 'daily-communication')),
  (71, 'Cry over spilled milk', 'Complain about something that cannot be fixed.', 'It''s broken, no use crying over spilled milk. (Than vãn chuyện đã rồi cũng vô ích.)', (select id from public.categories where slug = 'daily-communication')),
  (72, 'Elephant in the room', 'An obvious problem that everyone ignores.', 'Let''s address the elephant in the room: the budget cuts. (Hãy nói về vấn đề nhạy cảm: cắt giảm ngân sách.)', (select id from public.categories where slug = 'daily-communication')),
  (73, 'Fit as a fiddle', 'In very good health.', 'My grandpa is 80 but fit as a fiddle. (Ông tôi rất khỏe mạnh.)', (select id from public.categories where slug = 'daily-communication')),
  (74, 'Cold shoulder', 'To intentionally ignore someone.', 'She gave me the cold shoulder at the party. (Cô ấy phớt lờ tôi.)', (select id from public.categories where slug = 'daily-communication')),
  (75, 'Wild goose chase', 'A pointless or hopeless search.', 'Looking for that old file was a wild goose chase. (Tìm kiếm vô ích.)', (select id from public.categories where slug = 'daily-communication')),
  (76, 'Ignorance is bliss', 'Sometimes it''s better not to know.', 'I didn''t know they argued; ignorance is bliss. (Không biết lại tốt hơn.)', (select id from public.categories where slug = 'daily-communication')),
  (77, 'Leave no stone unturned', 'Try every possible option.', 'We will leave no stone unturned to find the bug. (Sẽ thử mọi cách có thể.)', (select id from public.categories where slug = 'daily-communication')),
  (78, 'Let the cat out of the bag', 'Reveal a hidden secret accidentally.', 'Who let the cat out of the bag about the merger? (Ai đã tiết lộ bí mật sáp nhập?)', (select id from public.categories where slug = 'daily-communication')),
  (79, 'Once in a blue moon', 'Happening very rarely.', 'I eat fast food once in a blue moon. (Tôi rất hiếm khi ăn đồ ăn nhanh.)', (select id from public.categories where slug = 'daily-communication')),
  (80, 'Steal someone''s thunder', 'Take credit or attention from someone else.', 'He stole my thunder by announcing his news first. (Anh ta đã cướp sự chú ý của tôi.)', (select id from public.categories where slug = 'daily-communication')),
  (81, 'Take with a grain of salt', 'Not take something too seriously or literally.', 'Take his promises with a grain of salt. (Nghe lời hứa của anh ta để tham khảo thôi.)', (select id from public.categories where slug = 'daily-communication')),
  (82, 'Through thick and thin', 'Supporting someone in all circumstances.', 'We stayed friends through thick and thin. (Sát cánh qua mọi thăng trầm.)', (select id from public.categories where slug = 'daily-communication')),
