  (87, 'By word of mouth', 'Through spoken communication.', 'We get most clients by word of mouth. (Chủ yếu qua truyền miệng.)', (select id from public.categories where slug = 'daily-communication')),
  (88, 'In the blink of an eye', 'Very quickly.', 'The car disappeared in the blink of an eye. (Biến mất trong nháy mắt.)', (select id from public.categories where slug = 'daily-communication')),
  (89, 'Out of the blue', 'Completely unexpectedly.', 'He called me out of the blue yesterday. (Gọi bất thình lình.)', (select id from public.categories where slug = 'daily-communication')),
  (90, 'A piece of work', 'A complicated or difficult person.', 'Your new boss is a real piece of work. (Sếp mới đúng là người khó xơi.)', (select id from public.categories where slug = 'daily-communication')),
  (91, 'Down to earth', 'Practical and realistic.', 'Despite his wealth, he is very down to earth. (Rất thực tế và bình dị.)', (select id from public.categories where slug = 'daily-communication')),
  (92, 'Go with the flow', 'To relax and accept a situation as it happens.', 'I don''t have a plan, I''ll just go with the flow. (Cứ để mọi chuyện tự nhiên.)', (select id from public.categories where slug = 'daily-communication')),
  (93, 'Hold your horses', 'Wait a moment; be patient.', 'Hold your horses, we aren''t ready to leave yet. (Bình tĩnh, chưa đi được đâu.)', (select id from public.categories where slug = 'daily-communication')),
  (94, 'Bite off more than you can chew', 'Take on a task that is way too big.', 'I bit off more than I could chew with this project. (Ôm đồm quá nhiều việc.)', (select id from public.categories where slug = 'daily-communication')),
  (95, 'Break the ice', 'Relieve tension in a new situation.', 'A joke is a good way to break the ice. (Phá vỡ bầu không khí ngại ngùng.)', (select id from public.categories where slug = 'daily-communication')),
  (96, 'Cross that bridge when you come to it', 'Deal with a problem only when it arises.', 'Don''t worry about next year, cross that bridge when you come to it. (Chuyện đâu còn có đó.)', (select id from public.categories where slug = 'daily-communication')),
  (97, 'Play it by ear', 'Decide how to act as a situation develops.', 'We don''t have a schedule, let''s play it by ear. (Tùy cơ ứng biến.)', (select id from public.categories where slug = 'daily-communication')),
  (98, 'Spit it out', 'Urging someone to say what they are hesitating about.', 'Just spit it out! What did he say? (Nói toẹt ra đi!)', (select id from public.categories where slug = 'daily-communication')),
  (99, 'Take a rain check', 'Politely decline but promise to do it later.', 'I''m busy today, can I take a rain check? (Hẹn dịp khác nhé?)', (select id from public.categories where slug = 'daily-communication')),
  (100, 'Circle back', 'To return to a topic at a later time.', 'Let''s circle back to the budget issue later. (Hãy quay lại vấn đề ngân sách sau.)', (select id from public.categories where slug = 'meetings-discussion')),
  (101, 'Open to suggestions', 'Willing to listen to new ideas.', 'I''m open to suggestions if you have a better way. (Rất sẵn lòng lắng nghe ý kiến.)', (select id from public.categories where slug = 'meetings-discussion')),
  (102, 'See your point', 'Acknowledging someone''s perspective.', 'I see your point, but we need to consider time. (Tôi hiểu ý bạn.)', (select id from public.categories where slug = 'meetings-discussion')),
  (103, 'Common ground', 'A point of agreement.', 'I think we can find some common ground. (Có thể tìm được điểm chung.)', (select id from public.categories where slug = 'meetings-discussion')),
