  (107, 'Agree to disagree', 'Accept that you won''t reach a consensus.', 'Let''s just agree to disagree. (Tạm gác lại bất đồng nhé.)', (select id from public.categories where slug = 'meetings-discussion')),
  (108, 'Confident that', 'Expressing strong belief.', 'I''m confident that this project will succeed. (Tôi tin chắc rằng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (109, 'Keep me in the loop', 'Keep someone informed.', 'Please keep me in the loop on updates. (Hãy cập nhật thông tin cho tôi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (110, 'Call it a day', 'Stop working for the day.', 'We''ve been at this for hours, let''s call it a day. (Hôm nay nghỉ thôi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (111, 'Take the lead', 'To be in charge of an action.', 'Why don''t you take the lead on the presentation? (Bạn dẫn dắt bài thuyết trình nhé?)', (select id from public.categories where slug = 'meetings-discussion')),
  (112, 'Think outside the box', 'Think creatively.', 'We need to think outside the box. (Cần suy nghĩ sáng tạo.)', (select id from public.categories where slug = 'meetings-discussion')),
  (113, 'Get up to speed', 'Get updated on information.', 'I''ll get you up to speed on what we discussed. (Cập nhật những gì đã thảo luận.)', (select id from public.categories where slug = 'meetings-discussion')),
  (114, 'Keep an eye on', 'Monitor closely.', 'Keep an eye on the development costs. (Theo dõi sát chi phí.)', (select id from public.categories where slug = 'meetings-discussion')),
  (115, 'Walk me through', 'Explain step-by-step.', 'Could you walk me through your proposal? (Giải thích chi tiết từng bước nhé?)', (select id from public.categories where slug = 'meetings-discussion')),
  (116, 'Bottom line', 'The most important conclusion.', 'The bottom line is we need to cut costs. (Vấn đề cốt lõi là phải giảm chi phí.)', (select id from public.categories where slug = 'meetings-discussion')),
  (117, 'On the same page', 'Have the same understanding.', 'Let''s ensure we''re all on the same page. (Đảm bảo tất cả hiểu giống nhau.)', (select id from public.categories where slug = 'meetings-discussion')),
  (118, 'Touch base', 'Briefly contact to update.', 'Let''s touch base early next week. (Liên lạc lại vào đầu tuần sau nhé.)', (select id from public.categories where slug = 'meetings-discussion')),
  (119, 'Worthwhile', 'Worth the time/effort.', 'This meeting was truly worthwhile. (Cuộc họp thực sự có giá trị.)', (select id from public.categories where slug = 'meetings-discussion')),
  (120, 'Back to the drawing board', 'Start over because of failure.', 'Our plan failed, back to the drawing board. (Làm lại từ đầu thôi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (121, 'Hit a snag', 'Encounter a minor problem.', 'We hit a minor snag with the shipment. (Gặp chút trở ngại nhỏ.)', (select id from public.categories where slug = 'meetings-discussion')),
  (122, 'Win-win situation', 'A result good for both sides.', 'This is a win-win situation. (Đôi bên cùng có lợi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (123, 'Cut to the chase', 'Get to the main point directly.', 'Let''s cut to the chase—can we meet the deadline? (Đi thẳng vào vấn đề đi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (124, 'Go over', 'To review something.', 'Could we go over the contract terms? (Xem lại các điều khoản nhé?)', (select id from public.categories where slug = 'meetings-discussion')),
  (125, 'Bring to the table', 'Offer something of value.', 'What skills do you bring to the table? (Bạn đóng góp được gì?)', (select id from public.categories where slug = 'meetings-discussion')),
  (126, 'Up in the air', 'Uncertain or undecided.', 'The date is still up in the air. (Vẫn chưa được quyết định.)', (select id from public.categories where slug = 'meetings-discussion')),
  (127, 'Iron out', 'Resolve minor problems.', 'We have a few details to iron out. (Còn vài chi tiết cần giải quyết.)', (select id from public.categories where slug = 'meetings-discussion')),
  (128, 'Stay on track', 'Continue as planned.', 'We need to stay on track with the schedule. (Đảm bảo đúng tiến độ.)', (select id from public.categories where slug = 'meetings-discussion')),
  (129, 'Bring up', 'Mention a topic for discussion.', 'I''d like to bring up the issue of overtime. (Đưa vấn đề ra thảo luận.)', (select id from public.categories where slug = 'meetings-discussion')),
  (130, 'Judgment call', 'A decision based on intuition.', 'I had to make a judgment call. (Tự đưa ra quyết định dựa trên kinh nghiệm.)', (select id from public.categories where slug = 'meetings-discussion')),
  (131, 'See eye to eye', 'To agree fully.', 'We don''t always see eye to eye. (Không phải lúc nào cũng đồng quan điểm.)', (select id from public.categories where slug = 'meetings-discussion')),
  (132, 'Clear the air', 'Resolve a misunderstanding.', 'Let’s chat to clear the air. (Làm rõ mọi chuyện và xóa căng thẳng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (133, 'Take into account', 'Consider something before deciding.', 'We must take into account the feedback. (Phải cân nhắc các phản hồi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (134, 'Stick to the point', 'Stay focused on the topic.', 'Please stick to the point. (Tập trung vào chủ đề chính.)', (select id from public.categories where slug = 'meetings-discussion')),
  (135, 'Fair enough', 'Accepting a point is reasonable.', 'Fair enough, just try to be on time. (Nghe hợp lý đấy.)', (select id from public.categories where slug = 'meetings-discussion')),
  (136, 'Run by', 'Get someone''s opinion on an idea.', 'I''ll run this idea by my boss. (Hỏi ý kiến sếp về ý tưởng này.)', (select id from public.categories where slug = 'meetings-discussion')),
  (137, 'Get the ball rolling', 'Start a process.', 'Let''s get the ball rolling today. (Bắt đầu triển khai ngay hôm nay.)', (select id from public.categories where slug = 'meetings-discussion')),
  (138, 'In the long run', 'Considering a long period into the future.', 'This will be beneficial in the long run. (Có lợi về lâu dài.)', (select id from public.categories where slug = 'meetings-discussion')),
  (139, 'Meet halfway', 'Compromise on an agreement.', 'Let''s meet halfway on the price. (Nhượng bộ nhau ở mức giữa đi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (140, 'Table the discussion', 'Postpone discussing a topic.', 'Let''s table the discussion until we have more data. (Gác lại cuộc thảo luận này đã.)', (select id from public.categories where slug = 'meetings-discussion')),
  (141, 'Take it offline', 'Discuss outside of the current larger meeting.', 'That''s a specific issue, let''s take it offline. (Hãy thảo luận riêng vấn đề này sau.)', (select id from public.categories where slug = 'meetings-discussion')),
  (142, 'Deep dive', 'A thorough and detailed exploration of a topic.', 'We need to do a deep dive into the Q3 metrics. (Cần phân tích chuyên sâu số liệu Q3.)', (select id from public.categories where slug = 'meetings-discussion')),
  (143, 'Action item', 'A specific task assigned to a person during a meeting.', 'John, your action item is to email the client. (John, nhiệm vụ của bạn là gửi email.)', (select id from public.categories where slug = 'meetings-discussion')),
  (144, 'Bandwidth', 'The capacity or time someone has to do work.', 'I don''t have the bandwidth to take on a new project. (Tôi không đủ thời gian/sức lực để nhận thêm việc.)', (select id from public.categories where slug = 'meetings-discussion')),
  (145, 'Core competency', 'A defining capability or advantage.', 'Software design is our company''s core competency. (Năng lực cốt lõi của công ty.)', (select id from public.categories where slug = 'meetings-discussion')),
  (146, 'Move the needle', 'Make a noticeable difference or impact.', 'This new ad campaign will really move the needle. (Sẽ tạo ra tác động rõ rệt.)', (select id from public.categories where slug = 'meetings-discussion')),
  (147, 'Paradigm shift', 'A fundamental change in approach.', 'AI is causing a paradigm shift in our industry. (Sự thay đổi mô hình mang tính bước ngoặt.)', (select id from public.categories where slug = 'meetings-discussion')),
  (148, 'Push the envelope', 'Extend the limits of what is possible.', 'We need to push the envelope with this new design. (Vượt qua những giới hạn cũ.)', (select id from public.categories where slug = 'meetings-discussion')),
  (149, 'Scalable', 'Able to grow and manage increased demand.', 'Is this database architecture truly scalable? (Có khả năng mở rộng không?)', (select id from public.categories where slug = 'meetings-discussion')),
  (150, 'Synergy', 'Combined power of working together.', 'There''s great synergy between our two teams. (Sự phối hợp cộng hưởng tuyệt vời.)', (select id from public.categories where slug = 'meetings-discussion')),
  (151, 'Traction', 'Progress or momentum of an idea/product.', 'Our new app is finally gaining traction in Asia. (Đang dần có được sức hút/sự chú ý.)', (select id from public.categories where slug = 'meetings-discussion')),
  (152, 'Wheelhouse', 'A person''s area of expertise.', 'Financial modeling is right in my wheelhouse. (Đúng chuyên môn/sở trường của tôi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (153, 'Elevator pitch', 'A very short, persuasive summary of an idea.', 'Give me your 30-second elevator pitch. (Bài thuyết trình ngắn gọn trong 30 giây.)', (select id from public.categories where slug = 'meetings-discussion')),
  (154, 'Game changer', 'An event/idea that significantly alters the current situation.', 'This technology is a total game changer. (Nhân tố thay đổi cục diện.)', (select id from public.categories where slug = 'meetings-discussion')),
  (155, 'Low-hanging fruit', 'Tasks or goals that are easily achievable.', 'Let''s focus on the low-hanging fruit first to get quick wins. (Mục tiêu dễ đạt được nhất.)', (select id from public.categories where slug = 'meetings-discussion')),
  (156, 'Boil the ocean', 'Undertake an impossible or overly broad task.', 'Don''t try to boil the ocean; just fix the main bug. (Đừng làm việc bao đồng/bất khả thi.)', (select id from public.categories where slug = 'meetings-discussion')),
  (157, 'Move the goalposts', 'Unfairly changing the rules or targets during a process.', 'It''s hard to succeed when management keeps moving the goalposts. (Thay đổi mục tiêu liên tục.)', (select id from public.categories where slug = 'meetings-discussion')),
  (158, 'Run it up the flagpole', 'Test an idea to see the reaction.', 'Let''s run this concept up the flagpole and see who salutes. (Thử nghiệm ý tưởng xem phản hồi ra sao.)', (select id from public.categories where slug = 'meetings-discussion')),
  (159, 'Put a pin in it', 'Hold onto an idea to discuss it later.', 'Let''s put a pin in that topic for next week''s meeting. (Ghim vấn đề đó lại để bàn sau.)', (select id from public.categories where slug = 'meetings-discussion')),
  (160, 'Herding cats', 'A futile attempt to control a disorganized group.', 'Managing this creative team is like herding cats. (Khó như quản lý một bầy mèo.)', (select id from public.categories where slug = 'meetings-discussion')),
  (161, 'In the weeds', 'Overwhelmed by excessive details.', 'We are getting too deep in the weeds on this minor issue. (Sa đà quá sâu vào tiểu tiết.)', (select id from public.categories where slug = 'meetings-discussion')),
  (162, 'Out of pocket', 'Unavailable or unreachable.', 'I will be out of pocket this weekend. (Tôi sẽ không thể liên lạc được/vắng mặt.)', (select id from public.categories where slug = 'meetings-discussion')),
  (163, 'Pivot', 'Fundamentally change the direction of a business strategy.', 'The startup had to pivot when their first product failed. (Chuyển hướng chiến lược.)', (select id from public.categories where slug = 'meetings-discussion')),
  (164, 'Unpack', 'To analyze or examine something in detail.', 'Let''s unpack the results of the survey. (Hãy mổ xẻ/phân tích chi tiết.)', (select id from public.categories where slug = 'meetings-discussion')),
  (165, 'Value-add', 'An extra feature that gives something greater value.', 'What is the specific value-add of your consulting service? (Giá trị gia tăng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (166, 'Optics', 'How a situation looks to the public or observers.', 'We can''t fire him now; the optics would be terrible. (Góc nhìn/dư luận.)', (select id from public.categories where slug = 'meetings-discussion')),
  (167, 'Best practice', 'The most effective and accepted way of doing something.', 'We should adopt industry best practices for cybersecurity. (Quy trình chuẩn mực nhất.)', (select id from public.categories where slug = 'meetings-discussion')),
  (168, 'Drill down', 'Look at something in more detail.', 'Let''s drill down into the demographic data. (Đi sâu vào chi tiết.)', (select id from public.categories where slug = 'meetings-discussion')),
  (169, 'Actionable', 'Able to be done or acted on.', 'We need actionable insights from this report, not just theories. (Có thể thực thi được.)', (select id from public.categories where slug = 'meetings-discussion')),
  (170, 'Alignment', 'Agreement and cooperation between groups.', 'We need complete alignment between sales and marketing. (Sự đồng bộ/liên kết.)', (select id from public.categories where slug = 'meetings-discussion')),
  (171, 'Consensus', 'General agreement among a group.', 'Have we reached a consensus on the budget? (Sự đồng thuận chung.)', (select id from public.categories where slug = 'meetings-discussion')),
  (172, 'Stakeholder', 'A person with an interest or concern in something.', 'We must update all external stakeholders. (Các bên liên quan.)', (select id from public.categories where slug = 'meetings-discussion')),
  (173, 'Deliverable', 'A thing able to be provided, especially a product of a process.', 'The final report is the key deliverable for phase one. (Sản phẩm bàn giao.)', (select id from public.categories where slug = 'meetings-discussion')),
  (174, 'Milestone', 'A significant stage in development.', 'Reaching 1 million users is a huge milestone. (Cột mốc quan trọng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (175, 'Pain point', 'A specific problem that customers are experiencing.', 'Our software solves a major pain point for accountants. (Điểm yếu/nỗi đau của khách hàng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (176, 'Touchpoint', 'Any point of contact between a buyer and a seller.', 'We need to improve the customer experience at every touchpoint. (Điểm chạm khách hàng.)', (select id from public.categories where slug = 'meetings-discussion')),
  (177, 'Metrics', 'Standards of measurement by which efficiency is assessed.', 'What metrics are we using to track success? (Các chỉ số đo lường.)', (select id from public.categories where slug = 'meetings-discussion')),
  (178, 'Get ahead of the curve', 'To be more advanced than competitors.', 'We need to innovate to get ahead of the curve. (Đổi mới để dẫn đầu xu thế.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (179, 'Throw in the towel', 'To admit defeat.', 'We won''t throw in the towel just yet. (Sẽ không bỏ cuộc sớm thế đâu.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (180, 'Back burner', 'Delay a project.', 'Put that project on the back burner. (Tạm gác dự án sang một bên.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (181, 'By the book', 'Follow rules strictly.', 'We do this strictly by the book. (Làm đúng theo quy định.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (182, 'In the pipeline', 'Being developed.', 'A new product is in the pipeline. (Đang phát triển sản phẩm mới.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (183, 'Take a backseat', 'Be less involved.', 'The CEO decided to take a backseat. (Bớt can thiệp vào việc hàng ngày.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (184, 'Green light', 'Permission to start.', 'We got the green light to begin. (Được phép bắt đầu.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (185, 'Level playing field', 'Fair situation.', 'Create a level playing field for competitors. (Tạo sân chơi bình đẳng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (186, 'Crunch time', 'High pressure period.', 'It''s crunch time, stay focused. (Đến giai đoạn nước rút.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (187, 'Steer clear of', 'Avoid a topic.', 'Steer clear of that topic during negotiation. (Tránh đề cập đến chủ đề đó.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (188, 'Smooth sailing', 'Easy process.', 'It hasn''t been smooth sailing, but we''re progressing. (Không hề dễ dàng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (189, 'Out of the loop', 'Not informed.', 'I''ve been out of the loop lately. (Không nắm được thông tin.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (190, 'Touch and go', 'Risky situation.', 'It was touch and go, but the deal was saved. (Tình thế vô cùng nguy hiểm.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (191, 'Jump the gun', 'Act prematurely.', 'Don''t jump the gun; wait for official data. (Đừng vội vàng quá.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (192, 'Draw the line', 'Set a strict limit.', 'I draw the line at working weekends. (Vạch rõ giới hạn.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (193, 'In the red', 'Losing money.', 'The company has been in the red for months. (Thua lỗ liên tục.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (194, 'See through', 'Finish a difficult project.', 'We have to see this project through. (Theo đuổi dự án đến cùng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (195, 'Put heads together', 'Collaborate.', 'Let’s put our heads together to solve this. (Cùng nhau thảo luận.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (196, 'Call the bluff', 'Challenge someone to prove a threat.', 'They threatened to quit, so I called their bluff. (Thách thức đối phương chứng minh.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (197, 'Keep options open', 'Avoid making a final decision immediately.', 'Let''s keep our options open before signing. (Cân nhắc các lựa chọn khác.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (198, 'Corner the market', 'Gain dominant control.', 'Our goal is to corner the market. (Thống lĩnh thị trường.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (199, 'Tighten belts', 'Reduce spending.', 'Due to lower sales, we need to tighten our belts. (Thắt chặt chi tiêu.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (200, 'Buy time', 'Delay to gain an advantage.', 'I need to buy some time to review documents. (Kéo dài thời gian.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (201, 'Go the extra mile', 'Make a special effort.', 'The team went the extra mile to finish. (Cực kỳ nỗ lực.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (202, 'Level head', 'Remain calm.', 'It’s vital to keep a level head during a crisis. (Giữ cái đầu lạnh.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (203, 'Up the ante', 'Increase the stakes.', 'The competitor upped the ante by lowering prices. (Tăng sức ép/cược.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (204, 'Brass tacks', 'Focus on basic facts.', 'Let''s get down to brass tacks. (Đi thẳng vào vấn đề chính.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (205, 'Hold your ground', 'Refuse to change your position.', 'They pressured me, but I held my ground. (Giữ vững lập trường.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (206, 'Take a hit', 'Suffer a financial loss.', 'Our profits will take a hit this quarter. (Lợi nhuận bị giảm sút.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (207, 'Beat the clock', 'Finish before the limit.', 'We worked all night to beat the clock. (Kịp thời hạn.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (208, 'Dealbreaker', 'An issue that causes a negotiation to fail.', 'Lack of technical support is a dealbreaker for us. (Yếu tố khiến thỏa thuận đổ vỡ.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (209, 'Hardball', 'Aggressive or ruthless behavior in business.', 'They are playing hardball on the pricing terms. (Chơi rắn/ép giá tàn nhẫn.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (210, 'Lowball', 'Offer an intentionally low price.', 'They tried to lowball us on the initial offer. (Đưa ra mức giá thấp bất hợp lý.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (211, 'Read the room', 'Understand the emotions and thoughts of the people present.', 'You need to read the room before pitching a risky idea. (Nắm bắt tâm lý đám đông/đối tác.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (212, 'Sweeten the deal', 'Add an extra incentive to an offer.', 'If you order 1000 units, I''ll sweeten the deal with free shipping. (Đưa ra thêm lợi ích hấp dẫn.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (213, 'Upper hand', 'The position of having power or control.', 'Having exclusive patents gives us the upper hand. (Chiếm ưu thế/nắm đằng chuôi.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (214, 'Leverage', 'Power to influence people and get the results you want.', 'We have immense leverage in this negotiation. (Lợi thế/đòn bẩy đàm phán.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (215, 'Call the shots', 'To be the person making all the important decisions.', 'When it comes to marketing, Sarah calls the shots. (Là người có quyền quyết định cuối cùng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (216, 'Back to square one', 'Forced to begin from the very start again.', 'The prototype failed, so it''s back to square one. (Trở lại vạch xuất phát.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (217, 'Get off the ground', 'Start to be successful or function.', 'It took years for the startup to get off the ground. (Bắt đầu cất cánh/thành công.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (218, 'Foot in the door', 'Get an initial opportunity in a company/market.', 'This internship is a great way to get your foot in the door. (Bước chân vào cửa/cơ hội ban đầu.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (219, 'Split the difference', 'Take the average of two proposed amounts.', 'You want $100, I offer $80; let''s split the difference at $90. (Cưa đôi khoảng cách/chia đều phần chênh lệch.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (220, 'Terms and conditions', 'The rules of a contract.', 'Always read the terms and conditions carefully. (Điều khoản và điều kiện.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (221, 'Ace up one''s sleeve', 'A secret advantage.', 'Our new AI feature is the ace up our sleeve. (Bảo bối bí mật/quân bài tẩy.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (222, 'Bargaining chip', 'Something used to gain an advantage in a negotiation.', 'We can use the delivery date as a bargaining chip. (Vật mặc cả/quân cờ đàm phán.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (223, 'Bide one''s time', 'Wait patiently for a good opportunity.', 'We are biding our time until the competitor goes bankrupt. (Kiên nhẫn chờ thời cơ.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (224, 'Cave in', 'To completely yield to pressure.', 'The company caved in to the union''s demands. (Chịu thua/nhượng bộ hoàn toàn.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (225, 'Close a deal', 'Successfully conclude a negotiation.', 'We finally closed the deal after three months of talks. (Chốt hợp đồng thành công.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (226, 'Drive a hard bargain', 'Expect a lot in exchange for what you pay.', 'She drives a hard bargain, but she is fair. (Mặc cả gay gắt/đàm phán rất giỏi.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (227, 'Force someone''s hand', 'Compel someone to act before they want to.', 'The leak to the press forced the CEO''s hand. (Ép ai đó phải hành động/lật bài ngửa.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (228, 'Hold all the cards', 'To be in a strong position with all the advantages.', 'In this monopoly, the supplier holds all the cards. (Nắm toàn quyền chủ động.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (229, 'Make a concession', 'Give up something in order to reach an agreement.', 'Both sides must make concessions to succeed. (Đưa ra sự nhượng bộ.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (230, 'Meet terms', 'Agree to the conditions set by someone.', 'We cannot meet your terms regarding the payment schedule. (Đáp ứng các điều khoản.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (231, 'Stand firm', 'Refuse to compromise.', 'We must stand firm on the security requirements. (Giữ vững lập trường, không khoan nhượng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (232, 'Take it or leave it', 'A non-negotiable offer.', 'This is our final offer, take it or leave it. (Nhận hoặc bỏ đi, không mặc cả thêm.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (233, 'Talk someone into', 'Persuade someone to do something.', 'He talked the investors into funding the project. (Thuyết phục ai đó làm gì.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (234, 'Walk away', 'Leave a negotiation without a deal.', 'Be prepared to walk away if the price is too high. (Sẵn sàng bỏ đi nếu không thỏa đáng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (235, 'Zero-sum', 'A situation where one person''s gain is another''s loss.', 'Business isn''t always a zero-sum game. (Trò chơi có tổng bằng không/được mất rõ ràng.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (236, 'Counter-offer', 'An offer made in response to another''s offer.', 'They rejected $50k and made a counter-offer of $60k. (Lời đề nghị ngược lại/đáp trả.)', (select id from public.categories where slug = 'negotiation-strategy')),
  (237, 'Deadlock', 'A situation where no progress can be made.', 'The peace talks have reached a deadlock. (Tình trạng bế tắc.)', (select id from public.categories where slug = 'negotiation-strategy')),
