  (272, 'Logistics', 'Detailed coordination of a complex operation.', 'The logistics of moving the office will be a nightmare. (Hậu cần/vận hành chi tiết.)', (select id from public.categories where slug = 'management-operations')),
  (273, 'Supply chain', 'Sequence of processes making and distributing a product.', 'The global supply chain was disrupted by the storm. (Chuỗi cung ứng.)', (select id from public.categories where slug = 'management-operations')),
  (274, 'Workflow', 'Sequence of industrial, administrative, or other processes.', 'This software will automate our entire approval workflow. (Quy trình/luồng công việc.)', (select id from public.categories where slug = 'management-operations')),
  (275, 'Agility', 'Ability to move and adapt quickly.', 'Agility is crucial for startups competing with giants. (Sự linh hoạt/nhanh nhạy.)', (select id from public.categories where slug = 'management-operations')),
  (276, 'Red tape', 'Excessive bureaucracy or adherence to rules.', 'There is too much red tape involved in getting a visa. (Thủ tục rườm rà/quan liêu.)', (select id from public.categories where slug = 'management-operations')),
