  (279, 'Ramp up', 'Increase the level or amount of something sharply.', 'We need to ramp up production for the holiday season. (Tăng cường/đẩy mạnh đột ngột.)', (select id from public.categories where slug = 'management-operations')),
  (280, 'Phase out', 'Gradually stop using or producing something.', 'We will phase out the old software over six months. (Loại bỏ dần dần.)', (select id from public.categories where slug = 'management-operations')),
