  (282, 'Lead time', 'Time between the initiation and completion of a process.', 'The lead time for manufacturing this part is 3 weeks. (Thời gian chờ từ lúc đặt hàng đến lúc giao.)', (select id from public.categories where slug = 'management-operations')),
  (283, 'Just-in-time', 'Inventory strategy reducing waste and response times.', 'We use just-in-time manufacturing to save warehouse space. (Sản xuất vừa đúng lúc.)', (select id from public.categories where slug = 'management-operations')),
  (284, 'Headcount', 'The number of people employed.', 'We have a freeze on headcount increases this year. (Tổng số nhân sự.)', (select id from public.categories where slug = 'management-operations')),
  (285, 'Go-live', 'The time when a system becomes operational.', 'The website go-live is scheduled for tomorrow at 8 AM. (Thời điểm hệ thống chính thức chạy.)', (select id from public.categories where slug = 'management-operations')),
  (286, 'Downtime', 'Time when a machine or system is out of action.', 'Server downtime cost us thousands of dollars. (Thời gian chết/hệ thống ngừng hoạt động.)', (select id from public.categories where slug = 'management-operations')),
  (287, 'Contingency plan', 'Plan for an unforeseen event.', 'Always have a contingency plan in case the supplier fails. (Kế hoạch dự phòng.)', (select id from public.categories where slug = 'management-operations')),
