  (289, 'Burn rate', 'Rate at which a company spends its capital.', 'Our startup''s burn rate is $50,000 per month. (Tốc độ đốt tiền/tiêu thụ vốn.)', (select id from public.categories where slug = 'management-operations')),
  (290, 'Backlog', 'Accumulation of uncompleted work.', 'We hired extra staff to clear the backlog of orders. (Khối lượng công việc tồn đọng.)', (select id from public.categories where slug = 'management-operations')),
  (291, 'Attrition', 'Gradual reduction of workforce by employees leaving.', 'High employee attrition is a sign of bad management. (Tỷ lệ nhân viên nghỉ việc tự nhiên.)', (select id from public.categories where slug = 'management-operations')),
  (292, 'Allocation', 'Action of distributing resources or duties.', 'Proper resource allocation is key to project success. (Sự phân bổ tài nguyên/ngân sách.)', (select id from public.categories where slug = 'management-operations')),
  (293, 'Scrum', 'Agile framework for managing knowledge work.', 'We have a 15-minute daily scrum meeting. (Khung làm việc Agile quản lý dự án.)', (select id from public.categories where slug = 'management-operations')),
  (294, 'Sprint', 'A set period to complete specific tasks.', 'Our dev team works in two-week sprints. (Giai đoạn chạy nước rút trong dự án.)', (select id from public.categories where slug = 'management-operations')),
  (295, 'Stand-up', 'A short daily meeting to coordinate the team.', 'Don''t be late for the morning stand-up. (Cuộc họp đứng/giao ban nhanh.)', (select id from public.categories where slug = 'management-operations')),
  (296, 'Outsourcing', 'Obtaining goods or a service from an outside supplier.', 'Outsourcing IT support saved us a lot of money. (Thuê ngoài dịch vụ.)', (select id from public.categories where slug = 'management-operations')),
  (297, 'Procurement', 'Action of obtaining equipment, materials, or services.', 'The procurement department handles purchasing raw materials. (Hoạt động thu mua/cung ứng.)', (select id from public.categories where slug = 'management-operations')),
