  (299, 'Please be advised', 'A formal way to notify the reader.', 'Please be advised that the office is closed. (Xin thông báo rằng.)', (select id from public.categories where slug = 'email-clients')),
  (300, 'As per our discussion', 'According to what was previously spoken about.', 'As per our discussion, I updated the timeline. (Theo như thảo luận của chúng ta.)', (select id from public.categories where slug = 'email-clients')),
  (301, 'Further to our conversation', 'Building upon a previous conversation.', 'Further to our conversation, here is the data. (Tiếp nối cuộc trò chuyện.)', (select id from public.categories where slug = 'email-clients')),
