  (324, 'Inconvenience caused', 'Trouble caused to a client.', 'Apologies for any inconvenience caused. (Sự bất tiện/phiền toái đã gây ra.)', (select id from public.categories where slug = 'email-clients')),
  (325, 'Meet requirements', 'Deliver what was specified.', 'We updated it to better meet your requirements. (Đáp ứng yêu cầu.)', (select id from public.categories where slug = 'email-clients')),
