  (327, 'Look into', 'Investigate thoroughly.', 'I will personally look into this error. (Đích thân xem xét/điều tra.)', (select id from public.categories where slug = 'email-clients')),
  (328, 'Circling back', 'Returning to a previous topic in an email.', 'Circling back on my previous email regarding the contract. (Quay lại vấn đề ở email trước.)', (select id from public.categories where slug = 'email-clients')),
