  (330, 'Per our last email', 'Referring to a previous email''s content.', 'Per our last email, the deadline is Friday. (Theo như email trước của chúng ta.)', (select id from public.categories where slug = 'email-clients')),
  (331, 'Moving forward', 'Looking to the future or next steps.', 'Moving forward, please send all requests to IT. (Kể từ nay trở đi/Hướng tới tương lai.)', (select id from public.categories where slug = 'email-clients')),
