  (337, 'Prompt response', 'A quick reply.', 'Thank you for your prompt response. (Phản hồi nhanh chóng.)', (select id from public.categories where slug = 'email-clients')),
  (338, 'Appreciate your patience', 'Thanking someone for waiting.', 'We appreciate your patience while we fix the server. (Cảm ơn vì đã kiên nhẫn chờ đợi.)', (select id from public.categories where slug = 'email-clients')),
  (339, 'Apologies for the delay', 'Saying sorry for being late to reply.', 'Apologies for the delay in getting back to you. (Xin lỗi vì sự chậm trễ.)', (select id from public.categories where slug = 'email-clients')),
  (340, 'Loop in', 'Include someone in an email chain.', 'I''m going to loop in David from Accounting. (Đưa ai đó vào vòng lặp trao đổi email.)', (select id from public.categories where slug = 'email-clients')),
  (341, 'CC / BCC', 'Carbon copy / Blind carbon copy.', 'Please CC me on all correspondence with the client. (Đồng kính gửi/Gửi ẩn danh.)', (select id from public.categories where slug = 'email-clients')),
  (342, 'Touch upon', 'Briefly mention or discuss a topic.', 'I wanted to touch upon the marketing budget. (Đề cập lướt qua/nhắc đến.)', (select id from public.categories where slug = 'email-clients')),
  (343, 'Clarify', 'Make a statement less confusing.', 'Could you clarify what you mean by ''ASAP''? (Làm rõ/giải thích rõ ràng.)', (select id from public.categories where slug = 'email-clients')),
  (344, 'Expedite', 'Make an action happen sooner.', 'Can we expedite the shipping process? (Thúc đẩy/đẩy nhanh tiến độ.)', (select id from public.categories where slug = 'email-clients')),
  (345, 'At your earliest convenience', 'Polite demand for quick action.', 'Please review this document at your earliest convenience. (Vui lòng xem xét sớm nhất có thể.)', (select id from public.categories where slug = 'email-clients')),
  (346, 'Enclosed', 'Included inside an envelope or physical package.', 'Please find enclosed the signed documents. (Được đính kèm trong thư.)', (select id from public.categories where slug = 'email-clients')),
  (347, 'Let me know if you have any questions', 'Standard closing offer for help.', 'Let me know if you have any questions regarding the quote. (Cho tôi biết nếu bạn có câu hỏi.)', (select id from public.categories where slug = 'email-clients')),
  (348, 'Please find attached', 'Directing attention to an email attachment.', 'Please find attached the Q3 financial report. (Vui lòng xem file đính kèm.)', (select id from public.categories where slug = 'email-clients')),
  (349, 'Reiterate', 'Say something again for clarity or emphasis.', 'I want to reiterate the importance of this deadline. (Nhấn mạnh lại/nhắc lại.)', (select id from public.categories where slug = 'email-clients')),
  (350, 'Pertaining to', 'Relating to or concerning something.', 'I have a question pertaining to your recent invoice. (Liên quan đến.)', (select id from public.categories where slug = 'email-clients')),
  (351, 'Accordingly', 'In a way that is appropriate to the circumstances.', 'The rules have changed, please adjust accordingly. (Phù hợp với điều đó/Tương ứng.)', (select id from public.categories where slug = 'email-clients')),
  (352, 'Herewith', 'With this letter or document.', 'I enclose herewith a copy of the policy. (Kèm theo thư này.)', (select id from public.categories where slug = 'email-clients')),
  (353, 'In response to', 'Answering a specific query or action.', 'I am writing in response to your advertisement. (Để phản hồi cho.)', (select id from public.categories where slug = 'email-clients')),
